import pytest

from bedrock_protocol import v1001, v2168, v2225

VERSIONS = [v1001, v2168, v2225]

# generated by gophertunnel b8bd735:
# packet.ServerStats{ServerTime: 12.5, NetworkTime: 0.25}
POSITIVE = bytes.fromhex("000048410000803e")

# generated by gophertunnel b8bd735:
# packet.ServerStats{ServerTime: -1, NetworkTime: 2.5}
NEGATIVE = bytes.fromhex("000080bf00002040")

GOLDENS = [
    *[
        pytest.param(
            version.ServerStatsPacket(server_time=12.5, network_time=0.25),
            POSITIVE,
            id=f"{version.__name__.removeprefix('bedrock_protocol.')}-positive",
        )
        for version in VERSIONS
    ],
    *[
        pytest.param(
            version.ServerStatsPacket(server_time=-1.0, network_time=2.5),
            NEGATIVE,
            id=f"{version.__name__.removeprefix('bedrock_protocol.')}-negative",
        )
        for version in VERSIONS
    ],
]


@pytest.mark.parametrize("version", VERSIONS, ids=lambda version: version.__name__.rpartition(".")[2])
def test_server_stats_is_packet_192(version):
    assert version.PACKETS[192] is version.ServerStatsPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_server_stats_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_server_stats_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
